import {PIECES,MISSIONS,missionById,dimensions,initialBuild,placePiece,reduceBuild,analyzeBuild,initialBuildSave,validateBuildSave} from './balance-lab.js';import {buildProjection,toBuildPoint,hitBuild,drawBuild} from './balance-view.js';
const BODY=`<div id="balance-panel" class="balance-panel"><nav id="balance-missions" class="balance-missions" aria-label="균형 놀이 고르기"></nav><div class="balance-heading"><h3 id="balance-title"></h3><p id="balance-goal"></p></div><div class="balance-layout"><section class="balance-work"><canvas id="balance-canvas" width="660" height="430" tabindex="0" role="application" aria-label="블록 작업장. 블록을 끌어 놓아요. 방향키로 위치, R로 회전, Enter로 놓기"></canvas><div class="balance-test-bar"><button data-balance-action="test" id="balance-test" class="primary">기울여 시험하기</button><button data-balance-action="edit" id="balance-edit">계속 고치기</button><button data-balance-action="center" id="balance-center" aria-pressed="false">무게중심 보기</button></div><p id="balance-status" role="status" aria-live="polite"></p><p id="balance-stats"></p><p class="balance-caption">반투명 블록은 다음 놓을 자리예요. 조립 중에는 고정하고 시험 때 균형을 확인해요.</p></section><section class="balance-toolbox"><h3>쌓을 블록</h3><div id="balance-pieces" class="balance-pieces"></div><label class="balance-existing-label">놓인 블록 고르기 <select id="balance-existing" data-balance-change="existing"><option value="">새 블록</option></select></label><p id="balance-selected"></p><div class="balance-position"><button data-balance-action="left" aria-label="고른 블록 왼쪽으로">←</button><button data-balance-action="rotate">90° 돌리기</button><button data-balance-action="right" aria-label="고른 블록 오른쪽으로">→</button><button data-balance-action="place" class="primary">여기에 놓기</button></div><p class="balance-caption">블록을 작업장으로 끌어도 돼요. 놓인 블록을 누르면 다시 옮길 수 있어요.</p><div class="balance-edits"><button data-balance-action="remove" id="balance-remove">고른 블록 빼기</button><button data-balance-action="undo" id="balance-undo">되돌리기</button><button data-balance-action="clear" id="balance-clear">다시 쌓기</button></div><p id="balance-save"></p><button data-balance-action="save" id="balance-save-retry" hidden>저장 다시 시도</button><details><summary>왜 균형이 달라질까?</summary><p id="balance-hint"></p><p>블록이 미는 힘과, 받침을 중심으로 돌리려는 효과를 함께 살펴봐요. 위에 올린 물건의 무게도 아래 받침에 전해져요.</p><p>빨간 점은 전체 무게중심, 노란 선은 닿아 있는 받침이에요. 전체 무게중심만으로 각 층의 균형을 판단할 수는 없어요.</p></details><details><summary>이 놀이가 계산하는 범위</summary><p>2차원에서 단단한 블록의 정적 균형을 계산해요. 미끄러지지 않는다고 가정하고 받침에 작은 여유를 둬요. 마찰·재료의 휨·충격·실제 무너지는 순서는 계산하지 않아요. 기울고 넘어지는 모습은 간단한 연출이에요.</p><p>실제 건축물의 안전을 검사하는 도구는 아니에요.</p></details></section></div></div>`;
export function createBalanceController({ui,getView,getProgress=()=>({}),transact=()=>false,discover=()=>{},doc=globalThis.document,win=globalThis.window,reduced=false}){
 let live=null;const $=id=>doc.querySelector('#'+id);
 function save(s){const completed=s.state.phase==='complete'?[...new Set([...s.saved.completed,s.state.mission])]:s.saved.completed;s.saved={...s.saved,selected:s.state.mission,completed,builds:{...s.saved.builds,[s.state.mission]:s.state.blocks}};const ok=transact({type:'SAVE_BUILD',build:s.saved});$('balance-save').textContent=ok?'쌓기와 완료 기록을 이 브라우저에 저장했어요':'저장하지 못했어요. 닫기 전에 다시 저장해 주세요';$('balance-save-retry').hidden=ok;return ok;}
 function clearDrag(s){const d=s.drag;s.drag=null;if(d)try{s.root.releasePointerCapture(d.id);}catch{}s.pointers.clear();}
 function close(){const s=live;if(!s)return;live=null;s.alive=false;clearDrag(s);s.state=reduceBuild(s.state,{type:'CANCEL'});s.visual.updateBuild?.(s.state);s.observer?.disconnect();for(const[node,type,fn]of s.listeners)node.removeEventListener(type,fn);}
 function draw(s){if(live!==s)return;const shown=reduced?{...s.state,testTime:0}:s.state;drawBuild(s.canvas.getContext('2d'),shown,{selectedId:s.selectedId,ghost:s.state.phase==='editing'?{id:s.selectedId,type:s.type,x:s.x,rot:s.rot}:null,showCenter:s.center,analysis:s.analysis});s.visual.updateBuild?.(shown);}
 function render(s,{changed=false}={}){if(live!==s)return;const testing=s.state.phase==='testing',mission=missionById(s.state.mission);if(changed){s.analysis=analyzeBuild(s.state.blocks,mission,0,{payload:false});$('balance-existing').innerHTML='<option value="">새 블록</option>'+s.state.blocks.map(b=>`<option value="${b.id}">${b.id.slice(1)}. ${PIECES[b.type].label} · 높이 ${b.y.toFixed(1)}</option>`).join('');}$('balance-existing').value=s.selectedId??'';$('balance-existing').disabled=testing;draw(s);$('balance-status').textContent=s.state.message;$('balance-status').dataset.phase=s.state.phase;const height=Math.max(0,...s.state.blocks.map(b=>b.y+dimensions(b).h));$('balance-stats').textContent=`블록 ${s.state.blocks.length} / 10 · 높이 ${height.toFixed(2)}칸 · 질량 ${s.analysis.mass.toFixed(1)}`;$('balance-selected').textContent=`${s.selectedId?'옮길 블록':'새 블록'}: ${PIECES[s.type].label} · 위치 ${s.x.toFixed(2)} · ${s.rot?'세로':'기본 방향'}`;$('balance-test').disabled=testing||!s.state.blocks.length;$('balance-edit').disabled=s.state.phase==='editing';$('balance-undo').disabled=testing||!s.state.history.length;$('balance-remove').disabled=testing||!s.selectedId;$('balance-clear').disabled=testing||!s.state.blocks.length;$('balance-center').setAttribute('aria-pressed',String(s.center));for(const b of s.root.querySelectorAll('[data-balance-action="piece"], [data-balance-action="left"], [data-balance-action="right"], [data-balance-action="rotate"], [data-balance-action="place"]'))b.disabled=testing;}
 function header(s){const m=missionById(s.state.mission);$('balance-missions').innerHTML=MISSIONS.map(m=>`<button data-balance-action="mission" data-id="${m.id}" aria-current="${m.id===s.state.mission?'step':'false'}">${m.title}${s.saved.completed.includes(m.id)?' ✓':''}</button>`).join('');$('balance-title').textContent=m.title;$('balance-goal').textContent=m.goal;$('balance-hint').textContent=m.hint;$('balance-pieces').innerHTML=Object.entries(PIECES).map(([id,p])=>`<button data-balance-action="piece" data-piece="${id}" aria-pressed="${id===s.type&&!s.selectedId}"><span class="balance-swatch" style="background:${p.color}"></span><strong>${p.label}</strong><small>${p.w} × ${p.h}${p.density>1?' · 질량 3배':''}</small></button>`).join('');}
 function mutate(s,next){if(live!==s||next===s.state)return;s.state=next;s.selectedId=null;save(s);header(s);render(s,{changed:true});}
 function place(s){const next=placePiece(s.state,s.type,s.x,s.rot,s.selectedId);if(next===s.state){s.state={...s.state,message:s.state.blocks.length>=10&&!s.selectedId?'블록은 최대 10개예요. 놓인 블록을 옮기거나 하나 빼 주세요':'여기에는 놓을 수 없어요. 위치를 조금 바꿔 봐요'};render(s);return;}mutate(s,next);}
 function edit(s){if(s.state.phase!=='editing')s.state=reduceBuild(s.state,{type:'EDIT'});}
 function bind(s,node,type,fn){node.addEventListener(type,fn);s.listeners.push([node,type,fn]);}
 function choose(s,id){if(!MISSIONS.some(m=>m.id===id))return;clearDrag(s);s.state=initialBuild(id,s.saved.builds[id]??[]);s.selectedId=null;s.type='wide';s.rot=false;s.x=0;save(s);header(s);render(s,{changed:true});}
 function locate(s,e){const r=s.canvas.getBoundingClientRect();return {inside:e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom,point:toBuildPoint(buildProjection(s.canvas.width,s.canvas.height),{x:(e.clientX-r.left)*s.canvas.width/r.width,y:(e.clientY-r.top)*s.canvas.height/r.height})};}
 function open(){if(live)return true;if(!getView()?.homeView)return false;return ui.workshop('균형 건축 놀이터',BODY,()=>{const saved=validateBuildSave(getProgress().homeBuild)??initialBuildSave(),s={alive:true,saved,state:initialBuild(saved.selected,saved.builds[saved.selected]??[]),root:$('balance-panel'),canvas:$('balance-canvas'),visual:getView().homeView,type:'wide',rot:false,x:0,selectedId:null,center:false,drag:null,pointers:new Set(),listeners:[],suppressClick:false};live=s;
  const resize=()=>{if(live!==s)return;const r=s.canvas.getBoundingClientRect();s.canvas.width=Math.max(200,Math.round(r.width));s.canvas.height=Math.max(240,Math.round(r.height));draw(s);};if(typeof ResizeObserver!=='undefined'){s.observer=new ResizeObserver(resize);s.observer.observe(s.canvas);}resize();
  bind(s,s.root,'click',e=>{if(live!==s)return;if(s.suppressClick){s.suppressClick=false;return;}const button=e.target.closest?.('[data-balance-action]');if(!button||!s.root.contains(button)||button.disabled)return;const a=button.dataset.balanceAction;if(a==='mission'){choose(s,button.dataset.id);return;}if(a==='save'){save(s);return;}if(a==='center'){s.center=!s.center;render(s);return;}if(a==='edit'){clearDrag(s);edit(s);render(s);return;}if(s.state.phase==='testing')return;if(a==='test'){clearDrag(s);s.state=reduceBuild(s.state,{type:'TEST'});render(s);return;}edit(s);if(a==='piece'){const type=button.dataset.piece;if(!Object.hasOwn(PIECES,type))return;s.type=type;s.selectedId=null;s.rot=false;header(s);}if(a==='rotate')s.rot=!s.rot;if(a==='left')s.x=Math.max(-4.5,s.x-.25);if(a==='right')s.x=Math.min(4.5,s.x+.25);if(a==='place'){place(s);return;}if(a==='remove'){mutate(s,reduceBuild(s.state,{type:'REMOVE',id:s.selectedId}));return;}if(a==='undo'||a==='clear'){clearDrag(s);mutate(s,reduceBuild(s.state,{type:a.toUpperCase()}));return;}render(s);});
  bind(s,s.root,'pointerdown',e=>{if(live!==s||s.state.phase==='testing'||e.button!==0)return;s.suppressClick=false;s.pointers.add(e.pointerId);if(s.pointers.size>1||e.isPrimary===false){clearDrag(s);return;}const piece=e.target.closest?.('[data-piece]'),fromTray=piece?.dataset?.piece&&Object.hasOwn(PIECES,piece.dataset.piece),onCanvas=e.target===s.canvas;if(!fromTray&&!onCanvas){s.pointers.delete(e.pointerId);return;}edit(s);const location=locate(s,e),hit=onCanvas?hitBuild(s.state.blocks,location.point):null;if(fromTray){s.type=piece.dataset.piece;s.rot=false;s.selectedId=null;}else if(hit){const block=s.state.blocks.find(b=>b.id===hit);s.selectedId=hit;s.type=block.type;s.rot=block.rot;s.x=block.x;}else{s.selectedId=null;s.x=location.point.x;}if(onCanvas)s.canvas.focus();
   s.drag={id:e.pointerId,startX:e.clientX,startY:e.clientY,fromTray:!!fromTray,hit,offset:hit?location.point.x-s.x:0,moved:false};try{s.root.setPointerCapture(e.pointerId);}catch{}e.preventDefault();header(s);render(s);
  });
  bind(s,s.root,'pointermove',e=>{const d=s.drag;if(live!==s||!d||d.id!==e.pointerId)return;d.moved=d.moved||Math.hypot(e.clientX-d.startX,e.clientY-d.startY)>6;const p=locate(s,e);s.x=Math.max(-4.5,Math.min(4.5,p.point.x-d.offset));draw(s);e.preventDefault();});
  bind(s,s.root,'pointerup',e=>{const d=s.drag;s.pointers.delete(e.pointerId);if(live!==s||!d||d.id!==e.pointerId)return;const p=locate(s,e),commit=p.inside&&(d.moved||(!d.fromTray&&!d.hit));clearDrag(s);s.suppressClick=d.moved||!!d.fromTray;if(commit){s.x=p.point.x-d.offset;place(s);}else render(s);});
  const cancel=e=>{if(!s.drag||e.pointerId===undefined||s.drag.id===e.pointerId){clearDrag(s);render(s);}};bind(s,s.root,'pointercancel',cancel);bind(s,s.root,'lostpointercapture',cancel);
  bind(s,s.root,'change',e=>{if(live!==s||s.state.phase==='testing'||e.target.dataset.balanceChange!=='existing')return;edit(s);const b=s.state.blocks.find(b=>b.id===e.target.value);s.selectedId=b?.id??null;if(b){s.type=b.type;s.rot=b.rot;s.x=b.x;}header(s);render(s);});
  bind(s,s.canvas,'keydown',e=>{if(s.state.phase==='testing'||live!==s)return;if(!['ArrowLeft','ArrowRight','r','R','Enter',' '].includes(e.key))return;e.preventDefault();edit(s);if(e.key==='ArrowLeft')s.x=Math.max(-4.5,s.x-.25);if(e.key==='ArrowRight')s.x=Math.min(4.5,s.x+.25);if(e.key.toLowerCase()==='r')s.rot=!s.rot;if(e.key==='Enter'||e.key===' '){place(s);return;}render(s);});
  const pause=()=>{if(live!==s)return;clearDrag(s);s.state=reduceBuild(s.state,{type:'CANCEL'});render(s);};bind(s,win,'blur',pause);bind(s,doc,'visibilitychange',()=>{if(doc.hidden)pause();});header(s);render(s,{changed:true});$('balance-save').textContent='블록은 자동 저장 · 실수해도 벌점은 없어요';return ()=>{if(live===s)close();};
 },{kind:'balance-workshop',closeLabel:'나가기'});}
 return {open,close,get active(){return !!live;},tick(dt){const s=live;if(!s||doc.hidden||s.state.phase!=='testing')return;const old=s.state;s.state=reduceBuild(s.state,{type:'TICK',dt:reduced?.1:dt});if(s.state.phase==='complete'&&old.phase!=='complete'){save(s);discover('home-stack');header(s);}render(s);},snapshot(){return live?structuredClone(live.state):null;}};
}
